namespace ghidra.app.plugin.core.debug.mapping;



using ghidra.debug.api.platform;
using ghidra.framework.plugintool;
using ghidra.program.model.lang;
using ghidra.program.model.lang;
using ghidra.trace.model;
using ghidra.trace.model.guest;
using ghidra.trace.model.target;

/**
 * An opinion which just uses the trace's "host" platform, i.e., because the target created the
 * trace with the correct host language. Other mappers assume the trace language is DATA, and that
 * the real language must be mapped as a guest platform.
 */
public class HostDebuggerPlatformOpinion : DebuggerPlatformOpinion {
	// An alternative default had better mean it.
	public static readonly int CONFIDENCE_HOST_KNOWN = 10000;

	protected static class HostDebuggerPlatformMapper : AbstractDebuggerPlatformMapper {
		public HostDebuggerPlatformMapper(PluginTool tool, Trace trace) : base(tool, trace)
    {
		}

		/* @Override */
		public CompilerSpec getCompilerSpec(TraceObject @object, long snap) {
			return trace.getBaseCompilerSpec();
		}

		/* @Override */
		public TracePlatform addToTrace(TraceObject newFocus, long snap) {
			return trace.getPlatformManager().getHostPlatform();
		}

		/* @Override */
		public bool canInterpret(TraceObject newFocus, long snap) {
			return true;
		}
	}

	class Offers : DebuggerPlatformOffer
{	public static readonly Offers HOST_UNKNOWN = new();
	public static readonly Offers HOST_KNOWN = new();


		/* @Override */
		public CompilerSpec getCompilerSpec() {
			return null;
		}

		/* @Override */
		public DebuggerPlatformMapper take(PluginTool tool, Trace trace) {
			return new HostDebuggerPlatformMapper(tool, trace);
		}

		/* @Override */
		public bool isCreatorOf(DebuggerPlatformMapper mapper) {
			return mapper.GetType() == typeof(HostDebuggerPlatformMapper);
		}
	}

	/* @Override */
	public Set<DebuggerPlatformOffer> getOffers(Trace trace, TraceObject focus, long snap,
			bool includeOverrides) {
		Processor processor = trace.getBaseLanguage().getProcessor();
		Processor procDATA = Processor.findOrPossiblyCreateProcessor("DATA");
		if (processor == procDATA) {
			return Set.of(Offers.HOST_UNKNOWN);
		}
		return Set.of(Offers.HOST_KNOWN);
	}
}
